import{_ as e,o as a,c as o,ao as d}from"./chunks/framework.CsA4OsPf.js";const F=JSON.parse('{"title":"AbstractFFTs","description":"","frontmatter":{},"headers":[],"relativePath":"reference/abstractffts.md","filePath":"reference/abstractffts.md","lastUpdated":null}'),l={name:"reference/abstractffts.md"};function s(n,t,r,c,f,i){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="AbstractFFTs" tabindex="-1">AbstractFFTs <a class="header-anchor" href="#AbstractFFTs" aria-label="Permalink to &quot;AbstractFFTs {#AbstractFFTs}&quot;">​</a></h1><p>FFTL is a backend of <a href="https://github.com/JuliaMath/AbstractFFTs.jl" target="_blank" rel="noreferrer">AbstractFFTs.jl</a>. Which methods each plan type provides:</p><table tabindex="0"><thead><tr><th style="text-align:left;">method</th><th style="text-align:left;">complex plans</th><th style="text-align:left;">real plans (<code>rfft</code>, <code>brfft</code>, <code>irfft</code>)</th><th style="text-align:left;">real-to-real plans</th></tr></thead><tbody><tr><td style="text-align:left;"><code>AbstractFFTs.Plan</code> supertype</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;"><code>size</code>, <code>ndims</code></td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;"><code>AbstractFFTs.fftdims</code></td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;"><code>mul!(y, p, x)</code></td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;"><code>p * x</code></td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;"><code>AbstractFFTs.plan_inv</code> (<code>inv(p)</code>, <code>p \\ y</code>)</td><td style="text-align:left;">✓ (<code>ScaledPlan</code>)</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr></tbody></table><p>Real plans are <code>RFFTLPlan</code> (<code>rfft</code>) and <code>BRFFTLPlan</code> (<code>brfft</code>, <code>irfft</code>); the complex ones are <code>FFTLPlan</code>; real-to-real are <code>R2RPlan</code>.</p><h2 id="The-generic-functions" tabindex="-1">The generic functions <a class="header-anchor" href="#The-generic-functions" aria-label="Permalink to &quot;The generic functions {#The-generic-functions}&quot;">​</a></h2><p>FFTL&#39;s exported <code>fft</code>, <code>plan_fft</code>, … are its own functions, not AbstractFFTs&#39;s. For generic code, FFTL adds methods to AbstractFFTs&#39;s <code>plan_fft</code>, <code>plan_bfft</code>, <code>plan_fft!</code>, <code>plan_bfft!</code>, <code>plan_rfft</code> and <code>plan_brfft</code> for arrays of floating-point numbers; AbstractFFTs derives the transform functions, the normalised inverses and the promotion of real input from them. So <code>AbstractFFTs.fft(x)</code> runs on FFTL when no other backend is loaded.</p><p>These methods are less specific than FFTW.jl&#39;s, which take <code>StridedArray</code>s of <code>Float32</code> and <code>Float64</code> values. With FFTW.jl loaded, the generic functions therefore run on FFTW for those arrays and on FFTL for the others (other floating-point types, non-strided arrays). Code that wants FFTL calls FFTL&#39;s functions; see <a href="/FFTL.jl/previews/PR18/howto/fftw#Coming-from-FFTW.jl">Coming from FFTW.jl</a>.</p><h2 id="Inverses" tabindex="-1">Inverses <a class="header-anchor" href="#Inverses" aria-label="Permalink to &quot;Inverses {#Inverses}&quot;">​</a></h2><p><code>inv(p)</code> of a forward complex plan is the normalised inverse, a <code>ScaledPlan</code> wrapping the backward plan. For a real-to-real plan, <code>inv</code> applies the partner kind and the normalisation of the kind; the factors are on <a href="/FFTL.jl/previews/PR18/howto/cosine_sine#Cosine,-sine-and-Hartley-transforms">Cosine, sine and Hartley transforms</a>.</p>',9)])])}const p=e(l,[["render",s]]);export{F as __pageData,p as default};
